// ASYNC

export const cielo2tsFile = async (cieloPath: string, tsPath: string = withExt(cieloPath, '.ts')): AutoPromise<string> => {

	assert(isFile(cieloPath), `No such file: ${OL(cieloPath)} (cielo2ts)`)
	assert((fileExt(cieloPath) === '.cielo'), `Not a cielo file: ${OL(cieloPath)}`)
	assert((fileExt(tsPath) === '.ts'), `Not a ts file: ${OL(tsPath)}`)
	const code = await Deno.readTextFile(cieloPath)
	const tsCode = await cielo2ts(code)
	await Deno.writeTextFile(tsPath, tsCode)
	assert(isFile(tsPath), `File not created: ${OL(tsPath)}`)
	return tsPath
}

